import kotlin.math.max

fun base(k: Long, l: Long): Long {
    var sum = 0L
    var num = k
    while (num != 0L) {
        sum += num % l
        num /= l
    }
    return sum
}

fun gcd(a: Long, b: Long): Long {
    return if (b == 0L) a else gcd(b, a % b)
}

fun main() {
    val n = readln().toLong()
    var f = 0L
    for (i in 2 until n) {
        f += base(n, i)
    }
    val denominator = n - 2
    if (denominator == 0L) {
        println("0/0") // Or handle as appropriate, though problem constraints usually imply n > 2
        return
    }
    val j = gcd(f, denominator)
    println("${f / j}/${denominator / j}")
}

